def find_input_for_function(f: callable, output: int) -> int:
    def binary_search():
        low, high = -10**6, 10**6  # Arbitrary large limits for the search space
        while low <= high:
            mid = (low + high) // 2
            result = f(mid)
            if result == output:
                return mid
            elif result < output:
                low = mid + 1
            else:
                high = mid - 1
        return None

    # Brute force search
    for i in range(-10**6, 10**6):
        if f(i) == output:
            return i

    # If brute force fails, attempt binary search
    return binary_search()

