from typing import List

def merge_sort(arr: List[int]) -> List[tuple]:
    if len(arr) > 1:
        mid = len(arr) // 2
        left_half = merge_sort(arr[:mid])
        right_half = merge_sort(arr[mid:])
        return merge(left_half, right_half)
    else:
        return arr

def merge(left: List[tuple], right: List[tuple]) -> List[tuple]:
    result = []
    left_idx, right_idx = 0, 0
    while left_idx < len(left) and right_idx < len(right):
        if left[left_idx][0] <= right[right_idx][0]:
            result.append(left[left_idx])
            left_idx += 1
        else:
            result.append(right[right_idx])
            right_idx += 1
    result.extend(left[left_idx:])
    result.extend(right[right_idx:])
    return result

def check_merge_sort_stability(arr: List[int]) -> bool:
    indexed_arr = list(enumerate(arr))
    sorted_indexed_arr = merge_sort(indexed_arr[:])
    sorted_arr = [x[0] for x in sorted_indexed_arr]
    for i in range(len(arr) - 1):
        if arr[sorted_arr[i]] == arr[sorted_arr[i + 1]] and sorted_arr[i] > sorted_arr[i + 1]:
            return False
    return True

