from typing import List, Tuple

def model_real_time_scheduler(tasks: List[Tuple[str, List[str]]]) -> bool:
    # Create a graph to represent tasks and dependencies
    from collections import defaultdict, deque

    # Graph adjacency list
    graph = defaultdict(list)
    # In-degree for cycle detection
    in_degree = defaultdict(int)

    # Build the graph
    for task, deps in tasks:
        for dep in deps:
            graph[dep].append(task)
            in_degree[task] += 1

    # Initialize a queue for tasks with no dependencies
    zero_in_degree_queue = deque()
    for task, _ in tasks:
        if in_degree[task] == 0:
            zero_in_degree_queue.append(task)

    # Kahn's algorithm for cycle detection
    processed_task_count = 0
    while zero_in_degree_queue:
        current_task = zero_in_degree_queue.popleft()
        processed_task_count += 1

        # Reduce in-degree by 1 for all its dependents
        for dependent in graph[current_task]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                zero_in_degree_queue.append(dependent)

    # If we processed all tasks, there's no cycle
    return processed_task_count == len(tasks)

def detect_cycle_bfs(graph: dict) -> bool:
    from collections import deque, defaultdict

    def bfs(start_node):
        visited = set()
        parent = defaultdict(lambda: None)
        queue = deque([(start_node, None)])
        while queue:
            node, par = queue.popleft()
            if node in visited:
                return True
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor == par:
                    continue
                if neighbor not in visited:
                    parent[neighbor] = node
                    queue.append((neighbor, node))
                elif parent[node] != neighbor:
                    return True
        return False

    visited_global = set()
    for node in graph:
        if node not in visited_global:
            if bfs(node):
                return True
            visited_global.add(node)
    return False

class BinarySearchTree:
    class Node:
        def __init__(self, key):
            self.left = None
            self.right = None
            self.value = key

    def __init__(self):
        self.root = None

    def insert(self, key):
        if self.root is None:
            self.root = self.Node(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        if key < node.value:
            if node.left is None:
                node.left = self.Node(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = self.Node(key)
            else:
                self._insert(node.right, key)

    def delete(self, key):
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if node is None:
            return node

        if key < node.value:
            node.left = self._delete(node.left, key)
        elif key > node.value:
            node.right = self._delete(node.right, key)
        else:
            if node.left is None:
                return node.right
            elif node.right is None:
                return node.left

            # Get the inorder successor (smallest in the right subtree)
            node.value = self._min_value_node(node.right).value
            node.right = self._delete(node.right, node.value)

        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def in_order_traversal(self):
        return self._in_order_traversal(self.root)

    def _in_order_traversal(self, node):
        res = []
        if node:
            res = self._in_order_traversal(node.left)
            res.append(node.value)
            res = res + self._in_order_traversal(node.right)
        return res

