def minimize_leftover_characters(s: str, dict: List[str]) -> int:
    word_set = set(dict)
    n = len(s)
    dp = [n] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for word in word_set:
            len_w = len(word)
            if i >= len_w and s[i - len_w:i] == word:
                dp[i] = min(dp[i], dp[i - len_w])
        dp[i] = min(dp[i], dp[i - 1] + 1)

    return dp[n]

