from typing import Dict, List

def find_eulerian_circuit(graph: Dict[int, List[int]]) -> List[int]:
    def is_connected_and_even_degree(graph):
        visited = set()
        def dfs(v):
            visited.add(v)
            for neighbor in graph[v]:
                if neighbor not in visited:
                    dfs(neighbor)

        start_vertex = None
        for vertex in graph:
            if graph[vertex]:
                start_vertex = vertex
                break

        if start_vertex is None:
            return True

        dfs(start_vertex)

        for vertex in graph:
            if (graph[vertex] and vertex not in visited) or len(graph[vertex]) % 2 != 0:
                return False
        return True

    if not is_connected_and_even_degree(graph):
        return []

    circuit = []
    stack = []
    current_vertex = next((v for v in graph if graph[v]), None)

    while stack or current_vertex is not None and graph[current_vertex]:
        if graph[current_vertex]:
            stack.append(current_vertex)
            neighbor = graph[current_vertex][-1]
            graph[current_vertex].remove(neighbor)
            graph[neighbor].remove(current_vertex)
            current_vertex = neighbor
        else:
            circuit.append(current_vertex)
            current_vertex = stack.pop()

    circuit.append(current_vertex)
    return circuit[::-1] if len(circuit) > 1 else []

