from typing import List

def solve_n_queens(n: int) -> List[List[str]]:
    def is_safe(row, col):
        return not (cols[col] or diagonals[row - col] or anti_diagonals[row + col])

    def place_queen(row, col):
        queens[row] = col
        cols[col] = True
        diagonals[row - col] = True
        anti_diagonals[row + col] = True

    def remove_queen(row, col):
        queens[row] = -1
        cols[col] = False
        diagonals[row - col] = False
        anti_diagonals[row + col] = False

    def add_solution():
        solution = []
        for row in range(n):
            line = ['.'] * n
            line[queens[row]] = 'Q'
            solution.append(''.join(line))
        solutions.append(solution)

    def backtrack(row = 0):
        for col in range(n):
            if is_safe(row, col):
                place_queen(row, col)
                if row + 1 == n:
                    add_solution()
                else:
                    backtrack(row + 1)
                remove_queen(row, col)

    queens = [-1] * n
    cols = [False] * n
    diagonals = [False] * (2 * n - 1)
    anti_diagonals = [False] * (2 * n - 1)
    solutions = []
    backtrack()
    return solutions

def longest_common_subsequence(str1: str, str2: str) -> int:
    m, n = len(str1), len(str2)
    # Create a 2D table to store lengths of longest common subsequence.
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp table.
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The length of the longest common subsequence is in the bottom-right corner.
    return dp[m][n]

