import heapq

def max_priority_queue(operations: List[Union[str, int]]) -> List[int]:
    max_heap = []
    result = []
    index = 0

    while index < len(operations):
        operation = operations[index]
        if operation == "insert":
            index += 1
            if index < len(operations) and isinstance(operations[index], int):
                heapq.heappush(max_heap, -operations[index])
            else:
                raise ValueError("Invalid operation sequence: 'insert' must be followed by an integer.")
        elif operation == "extract":
            if not max_heap:
                raise ValueError("Cannot perform 'extract' on an empty heap.")
            result.append(-heapq.heappop(max_heap))
        else:
            raise ValueError("Invalid operation: Supported operations are 'insert' and 'extract'.")
        index += 1

    return result

