from typing import List, Tuple, Any

class LRUCache:
    def __init__(self, capacity: int):
        self.cache = OrderedDict()
        self.capacity = capacity

    def insert(self, key: Any, value: Any) -> None:
        if key in self.cache:
            self.cache.pop(key)
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)
        self.cache[key] = value

    def retrieve(self, key: Any) -> Any:
        if key in self.cache:
            value = self.cache.pop(key)
            self.cache[key] = value
            return value
        return None

    def delete(self, key: Any) -> None:
        if key in self.cache:
            self.cache.pop(key)

def lru_cache_system(operations: List[Tuple[str, Any]]) -> List[Any]:
    cache_size = 2  # Assuming a fixed cache size of 2 for example purposes
    cache = LRUCache(cache_size)
    results = []
    for operation in operations:
        op_type = operation[0]
        if op_type == "insert":
            _, key, value = operation
            cache.insert(key, value)
        elif op_type == "retrieve":
            _, key = operation
            results.append(cache.retrieve(key))
        elif op_type == "delete":
            _, key = operation
            cache.delete(key)
    return results

