def maximize_clear_space(grid: List[List[str]]) -> int:
    max_area = 0
    rows, cols = len(grid), len(grid[0])

    def dfs(x, y, visited):
        if x < 0 or x >= rows or y < 0 or y >= cols or (x, y) in visited or grid[x][y] in ('B', 'T'):
            return 0
        visited.add((x, y))
        return (1 + dfs(x + 1, y, visited)
                + dfs(x - 1, y, visited)
                + dfs(x, y + 1, visited)
                + dfs(x, y - 1, visited))

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '.':
                visited = set()
                max_area = max(max_area, dfs(i, j, visited))

    return max_area

