from typing import List, Tuple

def detect_matching_phrases_across_documents(documents: List[str], phrase_length: int) -> List[Tuple[int, int]]:
    def hash_phrase(phrase: str) -> int:
        base = 256
        mod = 10**9 + 9
        h = 0
        for char in phrase:
            h = (h * base + ord(char)) % mod
        return h

    def rolling_hash_update(h: int, old_char: str, new_char: str, base_power: int) -> int:
        base = 256
        mod = 10**9 + 9
        h = (h - ord(old_char) * base_power) % mod
        h = (h * base + ord(new_char)) % mod
        return h

    phrases_map = {}
    base_power = pow(256, phrase_length - 1, 10**9 + 9)

    for doc_idx, document in enumerate(documents):
        n = len(document)
        if n < phrase_length:
            continue

        phrase = document[:phrase_length]
        curr_hash = hash_phrase(phrase)

        if curr_hash in phrases_map:
            phrases_map[curr_hash].add(doc_idx)
        else:
            phrases_map[curr_hash] = {doc_idx}

        for i in range(1, n - phrase_length + 1):
            phrase = document[i:i + phrase_length]
            curr_hash = rolling_hash_update(curr_hash, document[i - 1], document[i + phrase_length - 1], base_power)

            if curr_hash in phrases_map:
                phrases_map[curr_hash].add(doc_idx)
            else:
                phrases_map[curr_hash] = {doc_idx}

    results = []
    for doc_indices in phrases_map.values():
        if len(doc_indices) > 1:
            results.extend([(i, j) for i in doc_indices for j in doc_indices if i < j])

    return results

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

    def starts_with(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

    def auto_complete(self, prefix):
        def _dfs(current_node, path, results):
            if current_node.is_end_of_word:
                results.append(''.join(path))
            for char, next_node in current_node.children.items():
                _dfs(next_node, path + [char], results)

        results = []
        node = self.root
        for char in prefix:
            if char not in node.children:
                return results
            node = node.children[char]
        _dfs(node, list(prefix), results)
        return results

import sys

def estimate_memory_trie(trie):
    # Estimating memory usage for trie
    def _node_size(node):
        size = 0
        for _, next_node in node.children.items():
            size += _node_size(next_node)
        return size + sys.getsizeof(node)
    return _node_size(trie.root)

def estimate_memory_hash(words):
    # Estimating memory usage for hash table
    hash_table = {word: True for word in words}
    return sys.getsizeof(hash_table)

def trie_data_structure_comparison() -> str:
    example_words = ["apple", "app", "apricot", "banana", "band", "bat", "batch"]
    trie = Trie()
    for word in example_words:
        trie.insert(word)

    trie_memory_usage = estimate_memory_trie(trie)
    hash_memory_usage = estimate_memory_hash(example_words)

    trie_search_efficiency = trie.search("app")
    hash_search_efficiency = "app" in {word: True for word in example_words}

    return (
        f"Trie Memory Usage: {trie_memory_usage} bytes\n"
        f"Hash Table Memory Usage: {hash_memory_usage} bytes\n"
        f"Trie Search ('app'): {trie_search_efficiency}\n"
        f"Hash Table Search ('app'): {hash_search_efficiency}\n\n"
        "Trade-offs:\n"
        "1. Tries can be more memory-efficient for storing a large set of words with shared prefixes,\n"
        "   but typically use more memory than hash tables for small or dissimilar sets of words.\n"
        "2. Tries provide efficient prefix searching and auto-complete functionality.\n"
        "3. Hash tables provide faster exact match searches due to constant-time complexity,\n"
        "   but do not support prefix-based search operations efficiently.\n"
        "4. In terms of insertion, Tries can be slower due to node traversal compared to hash table insertions."
    )

