import random
import math
from typing import List, Tuple

def simulated_annealing(cities: List[Tuple[int, int]], initial_temp: float, cooling_rate: float, iterations: int) -> List[int]:
    def distance(city1: Tuple[int, int], city2: Tuple[int, int]) -> float:
        return math.sqrt((city1[0] - city2[0])**2 + (city1[1] - city2[1])**2)

    def total_distance(order: List[int]) -> float:
        total = 0.0
        for i in range(len(order)):
            city1 = cities[order[i]]
            city2 = cities[order[(i + 1) % len(order)]]
            total += distance(city1, city2)
        return total

    def swap(order: List[int]) -> List[int]:
        i, j = random.sample(range(len(order)), 2)
        new_order = order[:]
        new_order[i], new_order[j] = new_order[j], new_order[i]
        return new_order

    current_order = list(range(len(cities)))
    current_distance = total_distance(current_order)
    temp = initial_temp

    for _ in range(iterations):
        new_order = swap(current_order)
        new_distance = total_distance(new_order)

        if new_distance < current_distance or random.random() < math.exp((current_distance - new_distance) / temp):
            current_order, current_distance = new_order, new_distance

        temp *= cooling_rate

    return current_order

def solve_travelling_salesman_problem_with_annealing(cities: List[Tuple[int, int]]) -> List[int]:
    return simulated_annealing(cities, initial_temp=1000.0, cooling_rate=0.99, iterations=10000)

