class Node:
    def __init__(self, value):
        self.value = value
        self.next = None

class CircularLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def insert(self, position, value):
        new_node = Node(value)
        if self.head is None:
            new_node.next = new_node
            self.head = new_node
            self.tail = new_node
        else:
            if position == 0:
                new_node.next = self.head
                self.tail.next = new_node
                self.head = new_node
            else:
                current = self.head
                for _ in range(position - 1):
                    current = current.next
                new_node.next = current.next
                current.next = new_node
                if position == self.size:
                    self.tail = new_node
        self.size += 1

    def display(self):
        if self.head is None:
            return []
        result = []
        current = self.head
        for _ in range(self.size):
            result.append(current.value)
            current = current.next
        return result

    def split(self, position):
        if position <= 0 or position >= self.size:
            raise ValueError("Invalid position for split.")

        first_half = CircularLinkedList()
        second_half = CircularLinkedList()

        current = self.head
        for _ in range(position):
            first_half.insert(first_half.size, current.value)
            current = current.next

        for _ in range(self.size - position):
            second_half.insert(second_half.size, current.value)
            current = current.next

        return first_half, second_half

class ExtendedBloomFilter:
    def __init__(self, size, hash_count):
        self.size = size
        self.hash_count = hash_count
        self.bit_array = [0] * size
        self.count_array = [0] * size

    def _hashes(self, item):
        return [hash(str(item) + str(i)) % self.size for i in range(self.hash_count)]

    def add(self, item):
        for i in self._hashes(item):
            self.bit_array[i] = 1
            self.count_array[i] += 1

    def contains(self, item):
        return all(self.bit_array[i] for i in self._hashes(item))

    def remove(self, item):
        if self.contains(item):
            for i in self._hashes(item):
                self.count_array[i] -= 1
                if self.count_array[i] == 0:
                    self.bit_array[i] = 0

