from collections import deque

def detect_cycle_bfs(nodes: List[int], edges: List[Tuple[int, int]]) -> bool:
    if not edges:
        return False

    graph = {node: [] for node in nodes}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()

    def bfs(start):
        queue = deque([(start, -1)])
        visited.add(start)

        while queue:
            current_node, parent = queue.popleft()

            for neighbor in graph[current_node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, current_node))
                elif parent != neighbor:
                    return True

        return False

    for node in nodes:
        if node not in visited:
            if bfs(node):
                return True
    return False

