def maximize_inventory_stock(capacity: int, demand: dict) -> dict:
    restocks = {}
    sorted_demand = sorted(demand.items(), key=lambda x: -x[1])
    for product, request in sorted_demand:
        if capacity <= 0:
            break
        restock_qty = min(request, capacity)
        restocks[product] = restock_qty
        capacity -= restock_qty
    return restocks

def bitwise_operations(a: int, b: int, positions: list[int]) -> tuple[int, int, int]:
    and_result = a & b
    or_result = a | b
    for pos in positions:
        a ^= (1 << pos)
    return and_result, or_result, a

