def design_distributed_storage_system(peers: List[Tuple[str, int]], file_size: int, connectivity: Dict[str, List[str]], bandwidths: Dict[Tuple[str, str], float]) -> Dict[str, List[int]]:
    peer_storage = {peer[0]: [] for peer in peers}
    peer_capacities = {peer[0]: peer[1] for peer in peers}

    # Calculate how many segments we will create
    num_peers = len(peers)
    segment_size = file_size // num_peers + (file_size % num_peers > 0)
    segments = [{}, *([None] * (num_peers - 1))]

    # Assign segments to peers
    for segment_idx in range(0, file_size, segment_size):
        allocated = False
        for peer, capacity in sorted(peers, key=lambda x: x[1], reverse=True):
            if peer_capacities[peer] >= segment_size:
                peer_storage[peer].append(segment_idx // segment_size)
                peer_capacities[peer] -= segment_size
                allocated = True
                break
        if not allocated:
            raise Exception("File cannot be distributed with the given peer capacities.")

    return peer_storage

