def efficient_file_reader(file_path: str, block_size: int) -> str:
    content = []
    with open(file_path, 'rb') as file:
        while True:
            block = file.read(block_size)
            if not block:
                break
            content.append(block)
    return b''.join(content).decode('utf-8')

