import heapq
import math

def solve_maze_with_a_star(grid: List[List[int]], start: Tuple[int, int], end: Tuple[int, int], heuristic: str) -> List[Tuple[int, int]]:
    def heuristic_cost(current, goal, heuristic_type):
        if heuristic_type == "manhattan":
            return abs(current[0] - goal[0]) + abs(current[1] - goal[1])
        elif heuristic_type == "euclidean":
            return math.sqrt((current[0] - goal[0]) ** 2 + (current[1] - goal[1]) ** 2)
        else:
            raise ValueError("Invalid heuristic specified. Use 'manhattan' or 'euclidean'.")

    def get_neighbors(pos):
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        result = []
        for direction in directions:
            neighbor = (pos[0] + direction[0], pos[1] + direction[1])
            if 0 <= neighbor[0] < len(grid) and 0 <= neighbor[1] < len(grid[0]) and grid[neighbor[0]][neighbor[1]] != 9:
                result.append(neighbor)
        return result

    open_set = []
    heapq.heappush(open_set, (0, start))
    came_from = {}
    g_score = {start: 0}
    f_score = {start: heuristic_cost(start, end, heuristic)}

    while open_set:
        current_f, current = heapq.heappop(open_set)

        if current == end:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            path.reverse()
            return path

        for neighbor in get_neighbors(current):
            tentative_g_score = g_score[current] + grid[neighbor[0]][neighbor[1]]
            if neighbor not in g_score or tentative_g_score < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g_score
                f_score[neighbor] = tentative_g_score + heuristic_cost(neighbor, end, heuristic)
                heapq.heappush(open_set, (f_score[neighbor], neighbor))

    return []  # Return empty path if no path is found

