def counting_sort_ages(ages: list[int]) -> list[int]:
    if not ages:
        return []

    max_age = max(ages)
    count = [0] * (max_age + 1)

    for age in ages:
        count[age] += 1

    sorted_ages = []
    for age, freq in enumerate(count):
        sorted_ages.extend([age] * freq)

    return sorted_ages

