def enhanced_bubble_sort_comparison(arr: list[int]) -> dict[str, int]:
    def bubble_sort(arr: list[int]) -> tuple[int, int]:
        n = len(arr)
        comparisons, swaps = 0, 0
        for i in range(n):
            for j in range(0, n-i-1):
                comparisons += 1
                if arr[j] > arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
                    swaps += 1
        return comparisons, swaps

    def enhanced_bubble_sort(arr: list[int]) -> tuple[int, int]:
        n = len(arr)
        comparisons, swaps = 0, 0
        for i in range(n):
            swapped = False
            for j in range(0, n-i-1):
                comparisons += 1
                if arr[j] > arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
                    swaps += 1
                    swapped = True
            if not swapped:
                break
        return comparisons, swaps

    # Create copies of the input list to sort
    arr_copy_standard, arr_copy_enhanced = arr[:], arr[:]
    standard_comparisons, standard_swaps = bubble_sort(arr_copy_standard)
    enhanced_comparisons, enhanced_swaps = enhanced_bubble_sort(arr_copy_enhanced)

    return {
        'standard_comparisons': standard_comparisons,
        'standard_swaps': standard_swaps,
        'enhanced_comparisons': enhanced_comparisons,
        'enhanced_swaps': enhanced_swaps
    }

class Graph:
    def __init__(self, edges):
        self.graph = {}
        for u, v in edges:
            self.graph.setdefault(u, []).append(v)
            self.graph.setdefault(v, []).append(u)

    def dfs(self, start):
        visited = set()
        result = []

        def recursive_dfs(node):
            if node not in visited:
                visited.add(node)
                result.append(node)
                for neighbor in self.graph.get(node, []):
                    recursive_dfs(neighbor)

        recursive_dfs(start)
        return result

    def iter_dfs(self, start):
        visited = set()
        stack = [start]
        result = []

        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                result.append(node)
                stack.extend(neighbor for neighbor in self.graph.get(node, []) if neighbor not in visited)

        return result

    def bfs(self, start):
        visited = set()
        queue = [start]
        result = []

        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.add(node)
                result.append(node)
                queue.extend(neighbor for neighbor in self.graph.get(node, []) if neighbor not in visited)

        return result

    def count_connected_components(self):
        visited = set()
        count = 0

        def recursive_dfs(node):
            if node not in visited:
                visited.add(node)
                for neighbor in self.graph.get(node, []):
                    recursive_dfs(neighbor)

        for node in self.graph:
            if node not in visited:
                recursive_dfs(node)
                count += 1

        return count

