from typing import List

def linear_regression_from_scratch(dataset: List[List[float]]) -> float:
    def mean(values: List[float]) -> float:
        return sum(values) / len(values)

    def variance(values: List[float], mean_value: float) -> float:
        return sum((x - mean_value) ** 2 for x in values)

    def covariance(x_values: List[float], x_mean: float, y_values: List[float], y_mean: float) -> float:
        return sum((x - x_mean) * (y - y_mean) for x, y in zip(x_values, y_values))

    n_data_points = len(dataset)
    n_features = len(dataset[0]) - 1

    if n_features == 0 or n_data_points < 2:
        return 0.0

    x = [d[0] for d in dataset]
    y = [d[1] for d in dataset]

    x_mean = mean(x)
    y_mean = mean(y)

    b1 = covariance(x, x_mean, y, y_mean) / variance(x, x_mean)
    b0 = y_mean - b1 * x_mean

    def predict(x_values: List[float]) -> List[float]:
        return [b0 + b1 * x_i for x_i in x_values]

    y_predicted = predict(x)

    ss_total = sum((y_i - y_mean) ** 2 for y_i in y)
    ss_residual = sum((y_i - y_pred) ** 2 for y_i, y_pred in zip(y, y_predicted))

    r_squared = 1 - (ss_residual / ss_total if ss_total != 0 else 0)
    return r_squared

def count_unique_palindromic_substrings(s: str) -> int:
    unique_palindromes = set()

    def expand_around_center(left: int, right: int):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            unique_palindromes.add(s[left:right+1])
            left -= 1
            right += 1

    for i in range(len(s)):
        # Odd length palindromes
        expand_around_center(i, i)
        # Even length palindromes
        expand_around_center(i, i+1)

    return len(unique_palindromes)

