from typing import List

def block_movement_game_logic(board: List[List[int]]) -> List[List[List[int]]]:
    result = []

    def move_down(board):
        for col in range(len(board[0])):
            empty_row = len(board) - 1
            for row in range(len(board) - 1, -1, -1):
                if board[row][col] != 0:
                    board[empty_row][col], board[row][col] = board[row][col], board[empty_row][col]
                    empty_row -= 1

    def find_components(board):
        def dfs(r, c, color, component):
            stack = [(r, c)]
            while stack:
                x, y = stack.pop()
                if visited[x][y] or board[x][y] != color:
                    continue
                visited[x][y] = True
                component.append((x, y))
                for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                    nx, ny = x + dr, y + dc
                    if 0 <= nx < len(board) and 0 <= ny < len(board[0]) and not visited[nx][ny]:
                        stack.append((nx, ny))

        visited = [[False for _ in range(len(board[0]))] for _ in range(len(board))]
        components = []
        for r in range(len(board)):
            for c in range(len(board[0])):
                if not visited[r][c] and board[r][c] != 0:
                    component = []
                    dfs(r, c, board[r][c], component)
                    if len(component) > 1:
                        components.append(component)

        return components

    def collapse_component(board, component):
        min_row = min(component, key=lambda x: x[0])[0]
        for r, c in component:
            board[r][c] = 0
        move_down(board)
        return component, min_row

    while True:
        components = find_components(board)
        if not components:
            break
        component_to_remove = min(components, key=len)
        collapse_row = min(component_to_remove, key=lambda x: x[0])[0]
        component, min_row = collapse_component(board, component_to_remove)
        result.append([row[:] for row in board])

    return result

# Example Usage
print(block_movement_game_logic([[1, 0, 0], [1, 2, 2], [0, 0, 1]]))

def find_connected_components(adjacency_list: dict) -> list:
    def dfs(node, visited, component):
        visited.add(node)
        component.add(node)
        for neighbor in adjacency_list[node]:
            if neighbor not in visited:
                dfs(neighbor, visited, component)

    visited = set()
    components = []

    for node in adjacency_list:
        if node not in visited:
            component = set()
            dfs(node, visited, component)
            components.append(component)

    return components

