def file_based_key_value_store(command: str, key: str, value: str = "") -> str:
    filename = "kv_store.txt"

    def read_store():
        store = {}
        try:
            with open(filename, "r") as file:
                for line in file:
                    k, v = line.strip().split("=", 1)
                    store[k] = v
        except FileNotFoundError:
            pass
        return store

    def write_store(store):
        with open(filename, "w") as file:
            for k, v in store.items():
                file.write(f"{k}={v}\n")

    store = read_store()

    if command == "store":
        store[key] = value
        write_store(store)
        return "OK"
    elif command == "retrieve":
        return store.get(key, "Key not found")
    elif command == "delete":
        if key in store:
            del store[key]
            write_store(store)
            return "Deleted"
        else:
            return "Key not found"
    else:
        return "Invalid command"

