def chromatic_number(graph: dict) -> tuple[int, dict]:
    colors = {}
    for vertex in sorted(graph, key=lambda x: len(graph[x]), reverse=True):
        neighbor_colors = set(colors.get(neigh) for neigh in graph[vertex] if neigh in colors)
        for color in range(1, len(graph) + 1):
            if color not in neighbor_colors:
                colors[vertex] = color
                break
    chromatic_number = max(colors.values())
    return chromatic_number, colors

