def sieve_and_prime_check(n: int, number: int) -> bool:
    primes = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if primes[p]:
            for i in range(p * p, n + 1, p):
                primes[i] = False
        p += 1
    return primes[number] if number <= n and number >= 2 else False

