from typing import Tuple

def longest_common_subsequence(s1: str, s2: str) -> Tuple[int, str]:
    n, m = len(s1), len(s2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[n][m]

    # Reconstruct the LCS from the dp table
    i, j = n, m
    lcs = []

    while i > 0 and j > 0:
        if s1[i - 1] == s2[j - 1]:
            lcs.append(s1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    lcs.reverse()

    return lcs_length, ''.join(lcs)

from typing import List

def n_queens_solver(n: int) -> List[List[int]]:
    def is_safe(queens, row, col):
        for r in range(row):
            c = queens[r]
            if c == col or c - r == col - row or c + r == col + row:
                return False
        return True

    def solve(row, queens):
        if row == n:
            solutions.append(queens[:])
            return
        for col in range(n):
            if is_safe(queens, row, col):
                queens.append(col)
                solve(row + 1, queens)
                queens.pop()

    solutions = []
    solve(0, [])
    return solutions

