class DecisionTreeNode:
    def __init__(self, feature=None, threshold=None, left=None, right=None, value=None):
        self.feature = feature
        self.threshold = threshold
        self.left = left
        self.right = right
        self.value = value

def gini_impurity(y):
    # Calculate Gini impurity
    unique_labels = set(y)
    impurity = 1.0
    for label in unique_labels:
        prob_of_label = y.count(label) / len(y)
        impurity -= prob_of_label ** 2
    return impurity

def split_dataset(X, y, feature, threshold):
    left_X, left_y, right_X, right_y = [], [], [], []
    for xi, yi in zip(X, y):
        if xi[feature] < threshold:
            left_X.append(xi)
            left_y.append(yi)
        else:
            right_X.append(xi)
            right_y.append(yi)
    return left_X, left_y, right_X, right_y

def best_split(X, y):
    best_gini = float('inf')
    best_feature, best_threshold = None, None
    n_features = len(X[0])
    for feature in range(n_features):
        thresholds = set(x[feature] for x in X)
        for threshold in thresholds:
            left_X, left_y, right_X, right_y = split_dataset(X, y, feature, threshold)
            gini_left = gini_impurity(left_y)
            gini_right = gini_impurity(right_y)
            gini = (len(left_y) / len(y)) * gini_left + (len(right_y) / len(y)) * gini_right
            if gini < best_gini:
                best_gini = gini
                best_feature = feature
                best_threshold = threshold
    return best_feature, best_threshold

def build_tree(X, y):
    # Check for termination condition
    if len(set(y)) == 1:
        return DecisionTreeNode(value=y[0])

    # Find the best split
    feature, threshold = best_split(X, y)
    if feature is None:
        return DecisionTreeNode(value=max(set(y), key=y.count))

    left_X, left_y, right_X, right_y = split_dataset(X, y, feature, threshold)
    left_node = build_tree(left_X, left_y)
    right_node = build_tree(right_X, right_y)

    return DecisionTreeNode(feature=feature, threshold=threshold, left=left_node, right=right_node)

def predict(input_tree, x):
    if input_tree.value is not None:
        return input_tree.value
    if x[input_tree.feature] < input_tree.threshold:
        return predict(input_tree.left, x)
    else:
        return predict(input_tree.right, x)

def decision_tree_classifier_from_scratch(X, y):
    tree = build_tree(X, y)

    class DecisionTreeClassifier:
        def __init__(self, tree):
            self.tree = tree

        def predict(self, X):
            return [predict(self.tree, xi) for xi in X]

    return DecisionTreeClassifier(tree)

