from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity: int):
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key: str):
        if key not in self.cache:
            return None
        # Move the accessed item to the end to show it was recently used
        self.cache.move_to_end(key)
        return self.cache[key]

    def set(self, key: str, value: str):
        if key in self.cache:
            # Remove the old value before updating, then move to end
            self.cache.move_to_end(key)
        self.cache[key] = value
        # If we exceed capacity, remove the oldest item
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

cache = LRUCache(10)  # Initialize with default size of 10

def cache_access(url: str, max_cache_size: int) -> str:
    global cache
    if cache.capacity != max_cache_size:
        cache = LRUCache(max_cache_size)

    cached_content = cache.get(url)
