def find_input_for_output(expected_output: List[int]) -> List[int]:
    def f(numbers: List[int]) -> List[int]:
        return [sum((x % n == 0 or n % x == 0) for x in numbers) - 1 for n in numbers]

    def match_output(numbers: List[int]) -> bool:
        return f(numbers) == expected_output

    num_length = len(expected_output)
