def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def digit_sum(n: int) -> int:
    return sum(int(digit) for digit in str(n))

def filter_numbers(x: int, y: int, z: int) -> List[int]:
    results = []
    for num in range(1, x + 1):
        if is_prime(num) and digit_sum(num) > y and num % z == 1:
            results.append(num)
    return results

