def depth_first_search(adj_list: dict, start_vertex: int) -> list:
    visited = []
    stack = [start_vertex]

    while stack:
        vertex = stack.pop()
        if vertex not in visited:
            visited.append(vertex)
            stack.extend(reversed(adj_list.get(vertex, [])))
    return visited

