def complex_condition_checker(expression: str) -> bool:
    stack = []
    max_depth = 0
    current_depth = 0

    for char in expression:
        if char == '(':
            stack.append(char)
            current_depth += 1
            max_depth = max(max_depth, current_depth)
        elif char == ')':
            if stack:
                stack.pop()
                current_depth -= 1
            else:
                return False

    return max_depth <= 2 and not stack


