def derive_polynomial(poly: str) -> str:
    terms = poly.replace('-', '+-').split('+')
    derived_terms = []

    for term in terms:
        if 'x' in term:
            if term.index('x') == 0:
                coeff = '1'
            else:
                coeff = term[:term.index('x')]

            if coeff == '':
                coeff = '1'
            elif coeff == '-':
                coeff = '-1'

            if 'x' in term and '^' in term:
                exponent = term[term.index('^')+1:]
                new_coeff = int(coeff) * int(exponent)
                new_exponent = int(exponent) - 1
                if new_exponent == 1:
                    derived_terms.append(f"{new_coeff}x")
                elif new_exponent == 0:
                    derived_terms.append(f"{new_coeff}")
                else:
                    derived_terms.append(f"{new_coeff}x^{new_exponent}")
            else:
                derived_terms.append(f"{coeff}")
        else:
            continue

    return '+'.join(derived_terms)

