class Node:
    def __init__(self, value):
        self.value = value
        self.right = None
        self.down = None


class LinkedList2D:
    def __init__(self, grid):
        self.head = None
        self.construct(grid)

    def construct(self, grid):
        """ Construct a 2D linked list from the initial grid. """
        if not grid or not grid[0]:
            return

        prev_row_start = None
        last_node = None

        for row in grid:
            row_start = None
            prev_node = None
            for value in row:
                new_node = Node(value)
                if not row_start:
                    row_start = new_node
                if prev_node:
                    prev_node.right = new_node
                prev_node = new_node
                if last_node:
                    last_node.down = new_node
                    last_node = last_node.right
            if not self.head:
                self.head = row_start
            prev_row_start = row_start
            last_node = prev_row_start

    def insert_row(self, row_index, row_values):
        """ Insert a row at the given index with the given values. """
        if not self.head:
            if row_index == 0:
                self.construct([row_values])
            return

        new_row = [Node(value) for value in row_values]
        prev_row = None
        current_row = self.head
        if row_index == 0:
            for i, node in enumerate(new_row):
                node.right = new_row[i+1] if i + 1 < len(new_row) else None
                node.down = current_row
                current_row = current_row.right if current_row else None
            self.head = new_row[0]
            return

        row_count = 0
        while current_row and row_count < row_index:
            prev_row = current_row
            current_row = current_row.down
            row_count += 1

        if prev_row:
            for i, node in enumerate(new_row):
                node.right = new_row[i+1] if i + 1 < len(new_row) else None
                node.down = current_row
                if prev_row:
                    prev_row.down, prev_row = node, prev_row.right
            if current_row:
                current_row = current_row.right

    def insert_column(self, col_index, col_values):
        """ Insert a column at the given index with the given values. """
        if not self.head:
            if col_index == 0:
                self.construct([[v] for v in col_values])
            return

        new_col = [Node(value) for value in col_values]
        prev_node = None
        current_node = self.head
        if col_index == 0:
            for i, node in enumerate(new_col):
                node.down = new_col[i+1] if i + 1 < len(new_col) else None
                node.right = current_node
                if i == 0:
                    self.head = node
                else:
                    prev_node.down = node
                prev_node = node
                if current_node:
                    current_node = current_node.down
            return

        row_count = 0
        while current_node and row_count < len(col_values):
            prev_node = current_node
            for _ in range(col_index - 1):
                if current_node:
                    current_node = current_node.right
            if current_node:
                new_node = Node(col_values[row_count])
                new_node.right = current_node.right
                current_node.right = new_node
                prev_node = current_node
                current_node = current_node.down
                new_node.down = prev_node.right.down if prev_node and prev_node.right else None
            row_count += 1

    def display(self):
        """ Display the 2D linked list. """
        row_start = self.head
        while row_start:
            current = row_start
            while current:
                print(current.value, end=" ")
                current = current.right
            print()
            row_start = row_start.down


