def binary_search_on_tree(tree: dict, value: int) -> dict:
    def search(node, path, depth):
        if node is None:
            return None
        path.append(node)
        if node == value:
            return {'path': path, 'depth': depth}
        left_child, right_child = tree.get(node, [None, None])
        result = search(left_child, path[:], depth + 1)
        if result is not None:
            return result
        return search(right_child, path[:], depth + 1)

    result = search('root', [], 0)
    return result if result is not None else {'path': [], 'depth': -1}

def binary_search_ascending(array: list[int], target: int) -> int:
    left, right = 0, len(array) - 1
    while left <= right:
        mid = left + (right - left) // 2
