def check_tree_health(nodes: List[int], edges: List[Tuple[int, int]], max_height_diff: int) -> Optional[List[Tuple[int, int]]]:
    adjustments = []
    for u, v in edges:
        u_height = nodes[u - 1]
        v_height = nodes[v - 1]
        if abs(u_height - v_height) > max_height_diff:
            if u_height > v_height:
                adjustments.append((v, u_height - max_height_diff))
            else:
                adjustments.append((u, v_height - max_height_diff))
    return adjustments if adjustments else None

