def clean_data(dataset: List[List[float]]) -> List[List[float]]:
    def calculate_means(cols: List[List[float]]) -> List[float]:
        means = []
        for col in cols:
            valid_vals = [val for val in col if val is not None]
            if valid_vals:
                means.append(sum(valid_vals) / len(valid_vals))
            else:
                means.append(None)
        return means

    def replace_missing_with_means(row: List[float], means: List[float]) -> List[float]:
        return [val if val is not None else means[idx] for idx, val in enumerate(row)]

