def find_max_xor_subarray(nums: List[int]) -> int:
    max_xor = 0
    n = len(nums)
    prefix_xor = [0] * (n + 1)

    for i in range(n):
        prefix_xor[i + 1] = prefix_xor[i] ^ nums[i]

    for i in range(n):
        for j in range(i + 1, n + 1):
            max_xor = max(max_xor, prefix_xor[j] ^ prefix_xor[i])

    return max_xor

