from typing import List, Tuple, Dict, Set
import heapq

def simulate_public_transit(graph: List[Tuple[str, str, int]]) -> List[str]:
    # Create a function to perform Dijkstra's algorithm
    def dijkstra(adj_list: Dict[str, List[Tuple[str, int]]], start: str) -> Dict[str, int]:
        distances = {node: float('inf') for node in adj_list}
        distances[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in adj_list[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return distances

    # Convert graph given as edge list to adjacency list
    adj_list = {}
    for u, v, w in graph:
        if u not in adj_list:
            adj_list[u] = []
        if v not in adj_list:
            adj_list[v] = []
        adj_list[u].append((v, w))
        adj_list[v].append((u, w))

    # Find all nodes and initiate a dictionary to count disrupted routes
    nodes = set(adj_list.keys())
    disrupted_count = {node: 0 for node in nodes}

    # Calculate shortest paths for each node as start point
    for node in nodes:
        shortest_paths = dijkstra(adj_list, node)

        # For each destination, find contribution count for each path
        for target in nodes:
            if node != target:
                path = reconstruct_path(node, target, adj_list, shortest_paths)
                for station in path:
                    if station != node and station != target:
                        disrupted_count[station] += 1

    # Identify critical station, those with highest disrupted routes
    max_disruption = max(disrupted_count.values())
    critical_stations = [node for node, count in disrupted_count.items() if count == max_disruption]

    return critical_stations

def reconstruct_path(start: str, target: str, adj_list: Dict[str, List[Tuple[str, int]]], distances: Dict[str, int]) -> List[str]:
    # Reconstruct the shortest path using the distances calculated via Dijkstra
    if distances[target] == float('inf'):
        return []

    path = []
    current_node = target
    while current_node != start:
        for neighbor, weight in adj_list[current_node]:
            if distances[neighbor] + weight == distances[current_node]:
                path.append(current_node)
                current_node = neighbor
                break
    path.append(start)
    return path[::-1]

def calculate_fibonacci(n: int) -> int:
    """Calculate the N-th Fibonacci number using dynamic programming. Use a dictionary to store the computed Fibonacci numbers.

    Args:
    n (int): The position in the Fibonacci sequence to compute. Must be a non-negative integer.

    Returns:
    int: The N-th Fibonacci number.

    Doctest example:
    >>> calculate_fibonacci(10)
    55
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    fib_cache = {0: 0, 1: 1}
    def fib_helper(x: int) -> int:
        if x not in fib_cache:
            fib_cache[x] = fib_helper(x - 1) + fib_helper(x - 2)
        return fib_cache[x]
    return fib_helper(n)

