import heapq

class DynamicAStar:
    def __init__(self, grid):
        self.grid = grid
        self.rows = len(grid)
        self.cols = len(grid[0])
        self.open_set = []
        self.closed_set = set()
        self.g_score = {}
        self.f_score = {}
        self.came_from = {}

    def heuristic(self, a, b):
        (x1, y1) = a
        (x2, y2) = b
        return abs(x1 - x2) + abs(y1 - y2)

    def neighbors(self, node):
        (x, y) = node
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < self.rows and 0 <= ny < self.cols:
                yield (nx, ny)

    def reconstruct_path(self, current):
        path = [current]
        while current in self.came_from:
            current = self.came_from[current]
            path.append(current)
        path.reverse()
        return path

    def update_obstacle(self, new_grid):
        self.grid = new_grid

    def a_star(self, start, end):
        self.open_set = []
        self.closed_set = set()
        self.g_score = {start: 0}
        self.f_score = {start: self.heuristic(start, end)}
        self.came_from = {}

        heapq.heappush(self.open_set, (self.f_score[start], start))

        while self.open_set:
            current = heapq.heappop(self.open_set)[1]

            if current == end:
                return self.reconstruct_path(current)

            self.closed_set.add(current)

            for neighbor in self.neighbors(current):
                if neighbor in self.closed_set:
                    continue
                if self.grid[neighbor[0]][neighbor[1]] == 1:
                    continue

                tentative_g_score = self.g_score[current] + 1

                if neighbor not in self.g_score or tentative_g_score < self.g_score[neighbor]:
                    self.came_from[neighbor] = current
                    self.g_score[neighbor] = tentative_g_score
                    self.f_score[neighbor] = tentative_g_score + self.heuristic(neighbor, end)
                    if neighbor not in [i[1] for i in self.open_set]:
                        heapq.heappush(self.open_set, (self.f_score[neighbor], neighbor))

        return []

def dynamic_a_star_environment(obstacle_grid, start, end):
    astar = DynamicAStar(obstacle_grid)
    return astar.a_star(start, end)

