def sorted_polynomial_union(poly1: list[list[int]], poly2: list[list[int]]) -> list[list[int]]:
    index1, index2 = 0, 0
    result = []

    while index1 < len(poly1) and index2 < len(poly2):
        exp1, exp2 = poly1[index1][1], poly2[index2][1]
        if exp1 == exp2:
            coef_sum = poly1[index1][0] + poly2[index2][0]
            if coef_sum != 0:
                result.append([coef_sum, exp1])
            index1 += 1
            index2 += 1
        elif exp1 > exp2:
            result.append(poly1[index1])
            index1 += 1
        else:
            result.append(poly2[index2])
            index2 += 1

    while index1 < len(poly1):
        result.append(poly1[index1])
        index1 += 1

    while index2 < len(poly2):
        result.append(poly2[index2])
        index2 += 1

    return result

