from typing import List

def max_subarray_sum_after_one_removal(nums: List[int]) -> int:
    if len(nums) == 1:
        return nums[0]

    n = len(nums)
    max_ending_here = [0] * n
    max_starting_here = [0] * n

    max_ending_here[0] = nums[0]
    for i in range(1, n):
        max_ending_here[i] = max(nums[i], max_ending_here[i - 1] + nums[i])

    max_starting_here[n - 1] = nums[n - 1]
    for i in range(n - 2, -1, -1):
        max_starting_here[i] = max(nums[i], max_starting_here[i + 1] + nums[i])

    max_sum_with_one_removal = float('-inf')
    max_without_removal = max_ending_here[0]

    for i in range(1, n):
        max_without_removal = max(max_without_removal, max_ending_here[i])

    for i in range(1, n - 1):
        max_sum_with_one_removal = max(max_sum_with_one_removal, max_ending_here[i - 1] + max_starting_here[i + 1])

    return max(max_sum_with_one_removal, max_without_removal)

