from collections import Counter, defaultdict

def can_form_palindrome(count: Dict[str, int]) -> bool:
    """Check if a palindrome can be formed from character frequencies."""
    odd_count = 0
    for freq in count.values():
        if freq % 2 != 0:
            odd_count += 1
        if odd_count > 1:
            return False
    return True

def backtrack(path: List[str], count: Dict[str, int], results: List[str], n: int):
    """Use backtracking to generate all half-palindromic permutations."""
    if len(path) == n:
        half_perm = ''.join(path)
        reversed_half = half_perm[::-1]
        results.append(half_perm + middle + reversed_half)
        return

    for char in count:
        if count[char] > 0:
            path.append(char)
            count[char] -= 1

            backtrack(path, count, results, n)

            path.pop()
            count[char] += 1

def palindromic_permutations(s: str) -> List[str]:
    """Generate all palindromic permutations of the given string."""
    char_count = Counter(s)

    if not can_form_palindrome(char_count):
        return []

    global middle
    middle = ""
    half_chars = []
    for char, freq in char_count.items():
        if freq % 2 != 0:
            middle = char
        half_chars.extend([char] * (freq // 2))

    results = []
    backtrack([], Counter(half_chars), results, len(half_chars))

    return results

def fibonacci_memo(n: int) -> int:
    memo = {0: 0, 1: 1}

    def fibonacci(n):
        if n not in memo:
            memo[n] = fibonacci(n - 1) + fibonacci(n - 2)
        return memo[n]

    return fibonacci(n)

