def transform_grid(grid: list[str]) -> list[str]:
    def is_valid(i: int, j: int) -> bool:
        row_count = col_count = 0

        # Check the row for consecutive 1's
        if j > 0 and grid[i][j - 1] == '1':
            row_count += 1
        if j < len(grid[0]) - 1 and grid[i][j + 1] == '1':
            row_count += 1

        # Check the column for consecutive 1's
        if i > 0 and grid[i - 1][j] == '1':
            col_count += 1
        if i < len(grid) - 1 and grid[i + 1][j] == '1':
            col_count += 1

        return row_count >= 2 or col_count >= 2

    rows, cols = len(grid), len(grid[0])
    result = [['0'] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '1' and is_valid(i, j):
                result[i][j] = '1'

    return [''.join(row) for row in result]

