def solve_n_queens(n: int) -> List[List[List[int]]]:
    def is_safe(board, row, col):
        for i in range(col):
            if board[row][i] == 1:
                return False
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False
        for i, j in zip(range(row, n, 1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False
        return True

    def solve_util(board, col):
        if col >= n:
            solutions.append([row[:] for row in board])
            return True
        res = False
        for i in range(n):
            if is_safe(board, i, col):
                board[i][col] = 1
                res = solve_util(board, col + 1) or res
                board[i][col] = 0
        return res

    solutions = []
    board = [[0] * n for _ in range(n)]
    solve_util(board, 0)
    return solutions

def find_connected_components(graph: dict[str, list[str]]) -> dict[str, list[list[str]]]:
    def dfs(node, visited, component):
        stack = [node]
        while stack:
            curr = stack.pop()
            if curr not in visited:
                visited.add(curr)
                component.append(curr)
                stack.extend(neigh for neigh in graph[curr] if neigh not in visited)

    def bfs(node, visited, component):
        queue = [node]
        while queue:
            curr = queue.pop(0)
            if curr not in visited:
                visited.add(curr)
                component.append(curr)
                queue.extend(neigh for neigh in graph[curr] if neigh not in visited)

    visited_dfs = set()
    visited_bfs = set()
    components_dfs = []
    components_bfs = []

    for node in graph:
        if node not in visited_dfs:
            component_dfs = []
            dfs(node, visited_dfs, component_dfs)
            components_dfs.append(component_dfs)

        if node not in visited_bfs:
            component_bfs = []
            bfs(node, visited_bfs, component_bfs)
            components_bfs.append(component_bfs)

    return {'DFS': components_dfs, 'BFS': components_bfs}

