def solve_linear_programming(objective_function: List[float], constraints: List[List[float]], boundaries: Tuple[float, float]) -> Tuple[List[float], float]:
    A = [constraint[:-1] for constraint in constraints]
    b = [constraint[-1] for constraint in constraints]
    boundary_conditions = [(boundaries[0], boundaries[1]) for _ in range(len(objective_function))]

    res = linprog(c=[-coeff for coeff in objective_function], A_ub=A, b_ub=b, bounds=boundary_conditions, method='highs')

