def binary_search_selector(arr: list[int], target: int, method: str) -> int:
    def iterative_binary_search(arr: list[int], target: int) -> int:
        low, high = 0, len(arr) - 1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                high = mid - 1
            else:
                low = mid + 1
        return -1

    def recursive_binary_search(arr: list[int], target: int, low: int, high: int) -> int:
        if low > high:
            return -1
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            return recursive_binary_search(arr, target, low, mid - 1)
        else:
            return recursive_binary_search(arr, target, mid + 1, high)

    if method == "iterative":
        return iterative_binary_search(arr, target)
    elif method == "recursive":
        return recursive_binary_search(arr, target, 0, len(arr) - 1)
    else:
        raise ValueError("Method must be 'iterative' or 'recursive'")

