from typing import List, Tuple
import heapq

class DualHeap:
    def __init__(self):
        self.min_heap = []
        self.max_heap = []
        self.entry_finder = {}
        self.REMOVED = '<removed>'
        self.counter = 0

    def insert(self, num):
        if num in self.entry_finder and self.entry_finder[num] != self.REMOVED:
            return
        entry = [num, self.counter]
        self.counter += 1
        self.entry_finder[num] = entry
        heapq.heappush(self.min_heap, entry)
        heapq.heappush(self.max_heap, [-num, self.counter])

    def delete(self, num):
        entry = self.entry_finder.pop(num, None)
        if entry is not None:
            entry[0] = self.REMOVED

    def extract_min(self):
        while self.min_heap:
            num, _ = heapq.heappop(self.min_heap)
            if num != self.REMOVED:
                del self.entry_finder[num]
                return num
        return None

    def extract_max(self):
        while self.max_heap:
            num, _ = heapq.heappop(self.max_heap)
            num = -num
            if num in self.entry_finder and self.entry_finder[num] != self.REMOVED:
                del self.entry_finder[num]
                return num
        return None


def dual_heap_structure(operations: List[Tuple[str, int]]) -> List[int]:
    dh = DualHeap()
    result = []

    for command, num in operations:
        if command == "insert":
            dh.insert(num)
        elif command == "delete":
            dh.delete(num)
        elif command == "extract_max":
            result.append(dh.extract_max())
        elif command == "extract_min":
            result.append(dh.extract_min())

    return result

