import re

def password_strength_checker(password: str) -> str:
    if len(password) < 8:
        return 'Weak'

    has_lower = bool(re.search(r'[a-z]', password))
    has_upper = bool(re.search(r'[A-Z]', password))
    has_digit = bool(re.search(r'[0-9]', password))
    has_special = bool(re.search(r'[\W_]', password))

    if all([has_lower, has_upper, has_digit, has_special]):
        return 'Strong'

    if len(password) >= 8 and (has_lower + has_upper + has_digit + has_special) >= 3:
        return 'Moderate'

    return 'Weak'

