from typing import List, Tuple

def knapsack_memoization(items: List[Tuple[int, int]], capacity: int) -> int:
    memo = {}

    def helper(index: int, remaining_capacity: int) -> int:
        if index >= len(items) or remaining_capacity <= 0:
            return 0
        if (index, remaining_capacity) in memo:
            return memo[(index, remaining_capacity)]

        weight, value = items[index]

        if weight > remaining_capacity:
            result = helper(index + 1, remaining_capacity)
        else:
            result = max(helper(index + 1, remaining_capacity),
                         value + helper(index + 1, remaining_capacity - weight))

        memo[(index, remaining_capacity)] = result
        return result

    return helper(0, capacity)

