from typing import List, Tuple

def linear_regression(data: List[Tuple[List[float], float]], test_data: List[List[float]]) -> Tuple[List[float], List[float]]:
    def predict(features: List[float], weights: List[float]) -> float:
        return sum(f * w for f, w in zip(features, weights))

    def gradient_descent(X: List[List[float]], y: List[float], alpha: float, iterations: int) -> List[float]:
        m = len(y)
        n = len(X[0])
        weights = [0.0] * n
        for _ in range(iterations):
            gradients = [0.0] * n
            for features, target in zip(X, y):
                prediction = predict(features, weights)
                for j in range(n):
                    gradients[j] += (prediction - target) * features[j]
            for j in range(n):
                weights[j] -= (alpha / m) * gradients[j]
        return weights

    X = [features for features, _ in data]
    y = [target for _, target in data]
    alpha = 0.01
    iterations = 1000
    weights = gradient_descent(X, y, alpha, iterations)

    predictions = [predict(features, weights) for features in test_data]

    return weights, predictions

