def detect_cycle_in_graph(graph: dict[str, list[str]]) -> bool:
    def dfs(node):
        if node in visiting:
            return True  # Cycle detected
        if node in visited:
            return False  # Already visited

        visiting.add(node)
        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    visiting = set()
    visited = set()

    for node in graph:
        if node not in visited:
            if dfs(node):
                return True

    return False

