def longest_alpha_substring(s: str) -> str:
    if not s:
        return ""

    max_substring = s[0]
    current_substring = s[0]

    for i in range(1, len(s)):
        if s[i] >= s[i - 1]:
            current_substring += s[i]
        else:
            if len(current_substring) > len(max_substring):
                max_substring = current_substring
            current_substring = s[i]

    if len(current_substring) > len(max_substring):
        max_substring = current_substring

    return max_substring

def longest_common_subsequence(s1: str, s2: str) -> int:
    # Get the lengths of the input strings
    m, n = len(s1), len(s2)

    # Create a table to store lengths of longest common subsequence
    # Initialize the table with zeroes
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the dp table from bottom up
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The value in dp[m][n] is the length of LCS
    return dp[m][n]

