def enhanced_sieve_of_eratosthenes(max_num: int) -> list:
    if max_num < 2:
        return []

    is_prime = [True] * (max_num + 1)
    p = 2
    while p * p <= max_num:
        if is_prime[p]:
            for i in range(p * p, max_num + 1, p):
                is_prime[i] = False
        p += 1

    return [p for p in range(2, max_num + 1) if is_prime[p]]

