import re

def edit_distance(word1, word2):
    """Calculate the edit distance between two words using DP."""
    len1, len2 = len(word1), len(word2)
    dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]

    for i in range(len1 + 1):
        for j in range(len2 + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            else:
                if word1[i - 1] == word2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = min(dp[i - 1][j - 1], dp[i][j - 1], dp[i - 1][j]) + 1
    return dp[-1][-1]

def suggest_edits(text: str, dictionary: list) -> list:
    words = re.findall(r'\b\w+\b', text)
    suggestions = []

    for word in words:
        min_distance = float('inf')
        closest_words = []

        for dict_word in dictionary:
            distance = edit_distance(word.lower(), dict_word.lower())
            if distance < min_distance:
                min_distance = distance
                closest_words = [dict_word]
            elif distance == min_distance:
                closest_words.append(dict_word)

        suggestions.append(closest_words)

    return suggestions

