from typing import List, Union

class MinStack:
    def __init__(self):
        self.stack = []
        self.min_stack = []

    def push(self, x: int):
        self.stack.append(x)
        if not self.min_stack or x <= self.min_stack[-1]:
            self.min_stack.append(x)

    def pop(self):
        if self.stack:
            top = self.stack.pop()
            if top == self.min_stack[-1]:
                self.min_stack.pop()

    def get_min(self) -> Union[int, None]:
        if self.min_stack:
            return self.min_stack[-1]
        return None


def add_min_functionality_in_stack(push_pop_seq: List[Union[str, int]]) -> List[Union[int, None]]:
    min_stack = MinStack()
    results = []
    for operation in push_pop_seq:
        if operation.startswith("push"):
            _, value = operation.split()
            min_stack.push(int(value))
        elif operation == "pop":
            min_stack.pop()
        elif operation == "min":
            results.append(min_stack.get_min())
    return results

