import time
import random

def quick_sort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quick_sort(left) + middle + quick_sort(right)

def merge_sort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

def sort_efficiency_comparison(arr: list) -> dict:
    arr_copy1 = arr.copy()
    arr_copy2 = arr.copy()

    start_time = time.perf_counter()
    quick_sort(arr_copy1)
    quick_sort_time = time.perf_counter() - start_time

    start_time = time.perf_counter()
    merge_sort(arr_copy2)
    merge_sort_time = time.perf_counter() - start_time

    return {
        'quick_sort': {
            'time_complexity': 'O(n log n)', 
            'space_complexity': 'O(log n)', 
            'real_time': quick_sort_time
        },
        'merge_sort': {
            'time_complexity': 'O(n log n)', 
            'space_complexity': 'O(n)', 
            'real_time': merge_sort_time
        }
    }

