def analyze_company_network(nodes: list, edges: list, start_node: str, end_node: str) -> dict:
    from collections import deque

    # Create the adjacency list for the graph
    graph = {node: [] for node in nodes}
    for edge in edges:
        graph[edge[0]].append(edge[1])
        graph[edge[1]].append(edge[0])

    # BFS to find the shortest path from start_node to end_node
    def bfs_shortest_path(start, end):
        queue = deque([(start, [start])])
        visited = set([start])
        while queue:
            current_node, path = queue.popleft()
            if current_node == end:
                return path
            for neighbor in graph[current_node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, path + [neighbor]))
        return []

    # DFS to find the count of reachable nodes from start_node
    def dfs_reachable_count(node):
        stack = [node]
        visited = set()
        while stack:
            current = stack.pop()
            if current not in visited:
                visited.add(current)
                for neighbor in graph[current]:
                    if neighbor not in visited:
                        stack.append(neighbor)
        return len(visited)

    shortest_path = bfs_shortest_path(start_node, end_node)
    reachable_nodes_count = dfs_reachable_count(start_node)

    return {
        'shortest_path': shortest_path,
        'reachable_nodes_count': reachable_nodes_count
    }

