from typing import List

def balance_simulator(actions: List[str]) -> bool:
    balance = 0
    stack = []

    for action in actions:
        if action == 'add_open':
            balance += 1
            stack.append('open')
        elif action == 'add_close':
            if balance == 0 or not stack or stack[-1] != 'open':
                return False
            balance -= 1
            stack.pop()
            stack.append('close')
        elif action == 'remove_last':
            if not stack:
                return False
            last = stack.pop()
            if last == 'open':
                balance -= 1
            elif last == 'close':
                balance += 1

    return balance == 0 and not stack

def parse_and_evaluate_expression(expression: str) -> int:
    def evaluate(tokens):
        def get_number():
            nonlocal i
            result = 0
            sign = 1
            if tokens[i] == '+':
                i += 1
            elif tokens[i] == '-':
                sign = -1
                i += 1
            while i < len(tokens) and tokens[i].isdigit():
                result = result * 10 + int(tokens[i])
                i += 1
            return sign * result

        def parse_parentheses():
            nonlocal i
            i += 1  # skip '('
            num = parse_expression()
            i += 1  # skip ')'
            return num

        def get_term():
            nonlocal i
            if tokens[i] == '(':
                return parse_parentheses()
            return get_number()

        def parse_term():
            result = get_term()
            while i < len(tokens) and tokens[i] in '*/':
                op = tokens[i]
                i += 1
                if op == '*':
                    result *= get_term()
                elif op == '/':
                    result = int(result / get_term())
            return result

        def parse_expression():
            nonlocal i
            result = parse_term()
            while i < len(tokens) and tokens[i] in '+-':
                op = tokens[i]
                i += 1
                if op == '+':
                    result += parse_term()
                elif op == '-':
                    result -= parse_term()
            return result

        i = 0
        return parse_expression()

    tokens = []
    num = ''
    for char in expression:
        if char.isdigit():
            num += char
        else:
            if num:
                tokens.append(num)
                num = ''
            if char in '+-*/()':
                tokens.append(char)
    if num:
        tokens.append(num)

    return evaluate(tokens)

