# Genetic Algorithm Implementation
class GeneticAlgorithm:
    def __init__(self, nn, population_size=100, crossover_rate=0.7, mutation_rate=0.01, generations=100):
        self.nn = nn
        self.population_size = population_size
        self.crossover_rate = crossover_rate
        self.mutation_rate = mutation_rate
        self.generations = generations

    def initial_population(self):
        return [np.random.randn(self.nn.num_weights) for _ in range(self.population_size)]

    def fitness(self, individual, dataset):
        self.nn.weights = individual
        return 1 / self.nn.evaluate(dataset)

    def selection(self, population, fitness_scores):
        probabilities = np.array(fitness_scores) / sum(fitness_scores)
        selected_indices = np.random.choice(len(population), size=self.population_size, p=probabilities)
        return [population[i] for i in selected_indices]

    def crossover(self, parent1, parent2):
        if np.random.rand() < self.crossover_rate:
            point = np.random.randint(1, self.nn.num_weights - 1)
            child1 = np.concatenate([parent1[:point], parent2[point:]])
            child2 = np.concatenate([parent2[:point], parent1[point:]])
            return child1, child2
        return parent1, parent2

    def mutate(self, individual):
        for i in range(self.nn.num_weights):
            if np.random.rand() < self.mutation_rate:
                individual[i] += np.random.randn()
        return individual

    def run(self, dataset):
        population = self.initial_population()
        for generation in range(self.generations):
            fitness_scores = [self.fitness(ind, dataset) for ind in population]
            selected_population = self.selection(population, fitness_scores)

            next_generation = []
            for i in range(0, self.population_size, 2):
                parent1, parent2 = selected_population[i], selected_population[i+1]
                child1, child2 = self.crossover(parent1, parent2)
                next_generation.append(self.mutate(child1))
                next_generation.append(self.mutate(child2))

            population = next_generation
            best_fitness = max(fitness_scores)
            print(f"Generation {generation}, Best Fitness: {best_fitness}")

