def find_strongly_connected_components(graph: dict) -> list:
    index = 0
    stack = []
    lowlink = {}
    index_map = {}
    on_stack = {}
    sccs = []

    def strongconnect(node):
        nonlocal index
        index_map[node] = index
        lowlink[node] = index
        index += 1
        stack.append(node)
        on_stack[node] = True

        for w in graph.get(node, []):
            if w not in index_map:
                strongconnect(w)
                lowlink[node] = min(lowlink[node], lowlink[w])
            elif on_stack[w]:
                lowlink[node] = min(lowlink[node], index_map[w])

        if lowlink[node] == index_map[node]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == node:
                    break
            sccs.append(scc)

    for node in graph:
        if node not in index_map:
            strongconnect(node)

    return sccs

