def ternary_search(sorted_array: list[int], target: int) -> int:
    def search(low, high):
        if low > high:
            return -1

        third = (high - low) // 3
        mid1 = low + third
        mid2 = high - third

        if sorted_array[mid1] == target:
            return mid1
        if sorted_array[mid2] == target:
            return mid2

        if target < sorted_array[mid1]:
            return search(low, mid1 - 1)
        elif target > sorted_array[mid2]:
            return search(mid2 + 1, high)
        else:
            return search(mid1 + 1, mid2 - 1)

    return search(0, len(sorted_array) - 1)

