def minimal_time_units(start: int, target: int) -> int:
    from collections import deque

    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, time_units = queue.popleft()

        if current == target:
            return time_units

        incremented = current + 1
        doubled = current * 2

        if incremented <= target and incremented not in visited:
            visited.add(incremented)
            queue.append((incremented, time_units + 1))

        if doubled <= target and doubled not in visited:
            visited.add(doubled)
            queue.append((doubled, time_units + 3))

