from typing import Optional, List, Dict

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def find_unique_subtree_sums(root: Optional[TreeNode]) -> List[TreeNode]:
    def post_order(node: Optional[TreeNode], subtree_sum_count: Dict[int, int]) -> int:
        if not node:
            return 0
        left_sum = post_order(node.left, subtree_sum_count)
        right_sum = post_order(node.right, subtree_sum_count)
        total_sum = node.val + left_sum + right_sum
        subtree_sum_count[total_sum] = subtree_sum_count.get(total_sum, 0) + 1
        return total_sum

    if not root:
        return []

    subtree_sum_count = {}
    post_order(root, subtree_sum_count)

    unique_nodes = []

    def find_unique_nodes(node: Optional[TreeNode]) -> None:
        if not node:
            return
        total_sum = node.val + (post_order(node.left, {}) if node.left else 0) + (post_order(node.right, {}) if node.right else 0)
        if subtree_sum_count[total_sum] == 1:
            unique_nodes.append(node)
        find_unique_nodes(node.left)
        find_unique_nodes(node.right)

    find_unique_nodes(root)

    return unique_nodes

from typing import List

def largest_island_area(matrix: List[List[int]]) -> int:
    def dfs(x, y):
        if x < 0 or y < 0 or x >= len(matrix) or y >= len(matrix[0]) or matrix[x][y] == 0:
            return 0
        matrix[x][y] = 0  # Mark as visited
        return 1 + dfs(x + 1, y) + dfs(x - 1, y) + dfs(x, y + 1) + dfs(x, y - 1)

    max_area = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] == 1:
                max_area = max(max_area, dfs(i, j))
    return max_area

