from typing import List

def minimize_path_sum(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize the first row and the first column
    for i in range(1, m):
        grid[i][0] += grid[i - 1][0]
    for j in range(1, n):
        grid[0][j] += grid[0][j - 1]

    # Fill in the rest of the grid
    for i in range(1, m):
        for j in range(1, n):
            grid[i][j] += min(grid[i - 1][j], grid[i][j - 1])

    return grid[m - 1][n - 1]

def calculate_array_metrics(arr: list) -> tuple:
    min_value = min(arr)
    max_value = max(arr)
    total_sum = sum(arr)
    average = total_sum / len(arr)
    return (min_value, max_value, total_sum, average)
